#include <stdio.h>

/* teste do desafio flag-de-aprovado — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen) e captura o stdout no proprio teste.
   Os arquivos temporarios sao POR CENARIO: um cenario nunca le a entrada
   nem a captura do outro. Nunca ha fclose de stdin/stdout — so fflush —
   para o freopen seguinte ficar legal (C11 7.21.4). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void flagDeAprovado(void);

SM_TEST(a_nota_8_levanta_a_flag) {
    /* o que a pessoa digita: 8 */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "8\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    flagDeAprovado();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a nota 8 levanta a flag", linha, "1\n",
              "8 alcanca 6: a comparacao devolve 1 e a flag guarda esse 1");
    /* a saida TERMINA na primeira linha — buffer novo com sentinel */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida e a flag e nada mais: uma linha so");
    fclose(f);
}

SM_TEST(a_nota_4_baixa_a_flag) {
    /* outra nota: a saida tem de MUDAR com a entrada */
    FILE *e = fopen("sm_entrada_2.tmp", "w");
    fprintf(e, "4\n");
    fclose(e);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
    flagDeAprovado();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a nota 4 baixa a flag", linha, "0\n",
              "4 nao alcanca 6: a comparacao devolve 0 e a flag guarda o 0");
    fclose(f);
}

SM_TEST(a_nota_6_ainda_aprova) {
    /* a borda da faixa: 6 alcanca 6, porque o sinal e >= */
    FILE *e = fopen("sm_entrada_3.tmp", "w");
    fprintf(e, "6\n");
    fclose(e);
    freopen("sm_entrada_3.tmp", "r", stdin);

    freopen("sm_saida_3.tmp", "w", stdout);
    flagDeAprovado();
    fflush(stdout);

    FILE *f = fopen("sm_saida_3.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a nota 6 ainda aprova", linha, "1\n",
              "o sinal >= aceita o igual: com 6 a flag continua levantada");
    fclose(f);
}

